function validateGenerationConfiguration(){
  const ns=needs(),target=Math.max(1,+deckSize.value||1);
  for(const r of rarities){
    if(!Number.isInteger(ns[r])||ns[r]<0)throw generationError(language==="es"?`La cantidad de rareza ${r} debe ser un entero mayor o igual a 0.`:`Rarity ${r} must be a non-negative integer.`);
  }
  if(rarityTotal()!==target)throw generationError(language==="es"?`La suma de rarezas (${rarityTotal()}) debe coincidir con Cartas por mazo (${target}).`:`Rarity total (${rarityTotal()}) must match Cards per deck (${target}).`);
  if(mode.value==="manual"){
    for(const r of rarities){
      let vals=colors.map(c=>+document.getElementById(`q${r}${c}`).value);
      if(vals.some(v=>!Number.isInteger(v)||v<0))throw generationError(language==="es"?`${r}: la distribución manual por color debe usar números enteros mayores o iguales a 0.`:`${r}: manual color distribution must use non-negative integers.`);
      let sum=vals.reduce((a,b)=>a+b,0);
      if(sum!==ns[r])throw generationError(language==="es"?`${r}: la distribución manual por color suma ${sum}, pero debe sumar ${ns[r]}.`:`${r}: manual color distribution totals ${sum}, but must total ${ns[r]}.`);
    }
  }else if(priorityMode.value==="fixed"){
    getPriority();
  }
  return true;
}
function generationError(message){const e=new Error(message);e.isGenerationError=true;return e}
function generate(){try{
  let count=Math.max(1,+deckCount.value||1);
  validateGenerationConfiguration();
  if(!Number.isInteger(+maxCopies.value)||+maxCopies.value<1)throw generationError(language==="es"?"Máx. copias por carta debe ser un entero de al menos 1.":"Max copies per card must be an integer of at least 1.");
  activeGenerationSeed=getGenerationSeed();activeGenerationRng=makeSeededRng(activeGenerationSeed);
  let used={};decks=[];
  while(deckNames.length<count)deckNames.push("");deckNames=deckNames.slice(0,count);
  for(let d=0;d<count;d++){
    let out=[];
    for(const r of rarities){
      let q=quota(r,activeGenerationRng);
      if(Object.values(q).reduce((a,b)=>a+b,0)!==needs()[r])throw generationError(language==="es"?`${r}: la distribución manual debe sumar ${needs()[r]}.`:`${r}: manual distribution must total ${needs()[r]}.`);
      for(const c of colors){
        let locked=cards.filter(x=>locks[d+"-"+x.n]&&x.rarity===r&&x.color===c&&!excluded.has(x.n));
        if(locked.length>q[c])throw generationError(language==="es"?`Mazo ${d+1}: hay demasiadas cartas bloqueadas de ${r} ${label(c)}.`:`Deck ${d+1}: too many locked ${r} ${label(c)} cards.`);
        for(const x of locked){
          const limit=respectInv.checked?Math.max(0,+x.qty||0):Math.max(+maxCopies.value,1);
          if((used[x.n]||0)>=limit)throw generationError(language==="es"?`Mazo ${d+1}: la carta #${x.n} ${cardName(x)} está bloqueada, pero no quedan copias disponibles para usarla simultáneamente.`:`Deck ${d+1}: locked card #${x.n} ${cardName(x)} has no copies left for simultaneous use.`);
          out.push(x);used[x.n]=(used[x.n]||0)+1
        }
        let n=q[c]-locked.length;
        let pool=shuffle(cards.filter(x=>!excluded.has(x.n)&&x.rarity===r&&x.color===c&&!locks[d+"-"+x.n]&&(!respectInv.checked||x.qty>0)&&((used[x.n]||0)<(respectInv.checked?x.qty:Math.max(+maxCopies.value,1)))),activeGenerationRng);
        if(pool.length<n){
          let available=pool.length;
          throw generationError(language==="es"
            ?`No se puede completar el Mazo ${d+1}: faltan ${n-available} carta(s) ${r} ${label(c)}. Disponibles: ${available}; necesarias: ${n}. Revisa colección, exclusiones, bloqueos, máximo de copias o distribución.`
            :`Deck ${d+1} cannot be completed: ${n-available} ${r} ${label(c)} card(s) short. Available: ${available}; needed: ${n}. Check collection, exclusions, locks, max copies, or distribution.`);
        }
        for(const x of pool.slice(0,n)){out.push(x);used[x.n]=(used[x.n]||0)+1}
      }
    }
    decks.push(out)
  }
  let statusEl=document.getElementById("status");if(statusEl){statusEl.style.display="none";statusEl.innerHTML=""}
  render()
}catch(e){
  let statusEl=document.getElementById("status");statusEl.className="card generation-error";statusEl.style.display="block";statusEl.innerHTML=`<strong>${language==="es"?"No se pudo generar el mazo":"Deck generation failed"}</strong><br><span class=bad>${e.message}</span>`
}}

const sortState={};
function sortIndicator(tableId,col){
  let st=sortState[tableId];
  if(!st||st.col!==col||st.dir==="base") return " ↕";
  return st.dir==="asc"?" ↑":" ↓";
}
function cycleSort(tableId,col){
  let st=sortState[tableId]||{col:null,dir:"base"};
  if(st.col!==col) st={col:col,dir:"asc"};
  else if(st.dir==="asc") st.dir="desc";
  else if(st.dir==="desc") st.dir="base";
  else st.dir="asc";
  sortState[tableId]=st;
  if(tableId==="collection"){renderCollection();}
  else if(tableId.startsWith("history-") && activeHistoryIndex!==null){showHistoryEntry(activeHistoryIndex);}
  else render();
}
function sortedRows(rows,tableId){
  let st=sortState[tableId];
  if(!st||st.dir==="base"||!st.col) return [...rows];
  let a=[...rows], col=st.col, mul=st.dir==="asc"?1:-1;
  a.sort((x,y)=>{
    let xv=x[col], yv=y[col];
    if(typeof xv==="number"&&typeof yv==="number") return (xv-yv)*mul;
    return String(xv).localeCompare(String(yv),language==="es"?"es":"en",{numeric:true,sensitivity:"base"})*mul;
  });
  return a;
}
function sortableHeader(tableId,col,text){return `<th class="sortable" onclick="cycleSort('${tableId}','${col}')">${text}${sortIndicator(tableId,col)}</th>`}


let swapContext=null;
function inventoryUsed(exceptDeckIndex=null,exceptCardNumber=null){
  let used={};
  decks.forEach((d,di)=>d.forEach(x=>{
    if(di===exceptDeckIndex && x.n===exceptCardNumber)return;
    used[x.n]=(used[x.n]||0)+1;
  }));
  return used;
}
function swapCandidateState(x,current,deckIndex,cardNumber,used,inDeck){
  let reasons=[];
  if(x.n===cardNumber)reasons.push(language==="es"?"Es la carta actual.":"This is the current card.");
  if(x.rarity!==current.rarity)reasons.push(language==="es"?"Rareza diferente.":"Different rarity.");
  if(excluded.has(x.n))reasons.push(language==="es"?"Carta excluida.":"Card is excluded.");
  if(inDeck.has(x.n))reasons.push(language==="es"?"Ya está en este mazo.":"Already in this deck.");
  let usedQty=used[x.n]||0;
  let limit=respectInv.checked?Math.max(0,+x.qty||0):Math.max(1,+maxCopies.value||1);
  let available=Math.max(0,limit-usedQty);
  if(respectInv.checked && x.qty<=0)reasons.push(language==="es"?"No tienes copias en la colección.":"No copies in collection.");
  else if(available<=0)reasons.push(respectInv.checked?(language==="es"?"Todas las copias disponibles están siendo usadas.":"All available copies are already in use."):(language==="es"?"Se alcanzó el máximo de copias permitido.":"Maximum allowed copies reached."));
  return {valid:reasons.length===0,reasons,available,usedQty};
}

function swapOptionHtml(x,state){
  let available=state.available;
  let avText=language==="es"?`${available} disponible${available===1?"":"s"}`:`${available} available`;
  return `<div class="swap-option ${state.valid?"":"unavailable"}"><span><b>#${x.n} ${cardNameHtml(x)}</b><span class="availability ${available<=0?"zero":""}">${avText}</span><br><span class=small>${colorIcon(x.color)} ${label(x.color)} · ${x.rarity} · ${language==="es"?"Colección":"Collection"} ×${x.qty}</span>${state.reasons.length?`<span class="reason">${state.reasons.join(" ")}</span>`:""}</span><button ${state.valid?"":'disabled'} onclick="replaceDeckCard(${x.n})">${T("changeCard")}</button></div>`;
}
function openSwapModal(deckIndex,cardNumber){
  let current=decks[deckIndex]?.find(x=>x.n===cardNumber);if(!current)return;
  swapContext={deckIndex,cardNumber};
  let used=inventoryUsed(deckIndex,cardNumber);
  let inDeck=new Set(decks[deckIndex].filter(x=>x.n!==cardNumber).map(x=>x.n));
  let candidates=cards.filter(x=>x.n!==cardNumber&&x.rarity===current.rarity);
  let entries=candidates.map(x=>({card:x,state:swapCandidateState(x,current,deckIndex,cardNumber,used,inDeck)}));
  let validCount=entries.filter(e=>e.state.valid).length;
  let same=entries.filter(e=>e.card.color===current.color).sort((a,b)=>a.card.n-b.card.n);
  let otherGroups=colors.filter(c=>c!==current.color).map(c=>({
    color:c,entries:entries.filter(e=>e.card.color===c).sort((a,b)=>a.card.n-b.card.n)
  })).filter(g=>g.entries.length);

  document.getElementById("swapTitle").textContent=`${T("replaceCard")}: ${current.name}`;
  let sameHtml=`<h3>${colorIcon(current.color)} ${T("sameColor")} — ${label(current.color)}</h3>`+
    (same.length?same.map(e=>swapOptionHtml(e.card,e.state)).join(""):`<p class=small>${language==="es"?"No hay cartas de esta rareza y color.":"No cards with this rarity and color."}</p>`);
  let otherHtml=`<hr><h3>${T("otherColors")}</h3><p class="small">⚠️ ${T("colorRuleWarning")}</p>`+
    (otherGroups.length?otherGroups.map(g=>`<h3>${colorIcon(g.color)} ${label(g.color)}</h3>${g.entries.map(e=>swapOptionHtml(e.card,e.state)).join("")}`).join("")
    :`<p class=small>${language==="es"?"No hay cartas de otros colores con esta rareza.":"No other-color cards with this rarity."}</p>`);

  document.getElementById("swapBody").innerHTML=
    `<p class="small">${colorIcon(current.color)} ${label(current.color)} · ${current.rarity} — ${T("availableReplacements")}: ${validCount}</p>`+
    sameHtml+otherHtml;
  document.getElementById("swapOverlay").classList.add("open");
}
function closeSwapModal(){document.getElementById("swapOverlay").classList.remove("open");swapContext=null}
function replaceDeckCard(newNumber){
  if(!swapContext)return;
  let {deckIndex,cardNumber}=swapContext,newCard=cards.find(x=>x.n===newNumber),d=decks[deckIndex];if(!newCard||!d)return;
  let idx=d.findIndex(x=>x.n===cardNumber);if(idx<0)return;
  let wasLocked=!!locks[deckIndex+"-"+cardNumber];
  delete locks[deckIndex+"-"+cardNumber];
  d[idx]=newCard;
  if(wasLocked)locks[deckIndex+"-"+newNumber]=true;
  closeSwapModal();render();
}


let cardImageByNumber={};
let cardImageDataLoaded=false;
let cardRulesByName={};
let cardRulesDataLoaded=false;
async function loadCardImageData(){
  if(cardImageDataLoaded)return;
  try{
    let response=await fetch("https://moodswingsdata.github.io/msw/printings.json");
    if(!response.ok)throw new Error("HTTP "+response.status);
    let printings=await response.json();
    printings.forEach(p=>{if(p.collector_number!=null&&p.card_image_url)cardImageByNumber[String(p.collector_number)]=p.card_image_url});
    cardImageDataLoaded=true;
  }catch(e){console.warn("Mood Swings card previews unavailable:",e)}
}

async function loadCardRulesData(){
  if(cardRulesDataLoaded)return;
  try{
    let response=await fetch("https://moodswingsdata.github.io/msw/cards.json");
    if(!response.ok)throw new Error("HTTP "+response.status);
    let data=await response.json();
    data.forEach(c=>{if(c.name)cardRulesByName[c.name.toLowerCase()]=c});
    cardRulesDataLoaded=true;
  }catch(e){console.warn("Mood Swings card rules unavailable:",e)}
}
function diceDisplay(c){
  if(!c)return "";
  let base=c.dice_value!=null?c.dice_value:"";
  let secondary=c.secondary_dice_value!=null?` → ${c.secondary_dice_value}`:"";
  return base!==""?`🎲 ${base}${secondary}`:"";
}
function cardNameHtml(x){return `<span class="card-name-wrap"><span class="card-name-preview" data-card-number="${x.n}">${x.name}</span><button type="button" class="card-note-btn" data-note-card="${x.n}" title="${language==="es"?"Ver información y notas":"View information and notes"}">ⓘ</button></span>`}

function decodeMoodHtml(text){
  let el=document.createElement("textarea");el.innerHTML=text||"";return el.value;
}
function stripMoodHtml(text){
  let el=document.createElement("div");el.innerHTML=decodeMoodHtml(renderMoodDiceNotation(text||""));return el.textContent||el.innerText||"";
}

function renderMoodDiceNotation(text){
  if(!text)return "";
  // Consecutive bracketed integers represent dice/value components.
  // Example: [6][1] => 7, [3] => 3.
  return String(text).replace(/(?:\[\d+\])+/g, token=>{
    const nums=[...token.matchAll(/\[(\d+)\]/g)].map(m=>Number(m[1]));
    return String(nums.reduce((sum,n)=>sum+n,0));
  });
}
function safeMoodHtml(text){
  let raw=decodeMoodHtml(renderMoodDiceNotation(text||""));
  let tpl=document.createElement("template");tpl.innerHTML=raw;
  tpl.content.querySelectorAll("*").forEach(el=>{
    if(!["STRONG","B","EM","I","BR"].includes(el.tagName))el.replaceWith(document.createTextNode(el.textContent||""));
    else [...el.attributes].forEach(a=>el.removeAttribute(a.name));
  });
  let html=tpl.innerHTML;
  // Turn references to other Mood Swings cards into hover/tap previews.
  if(typeof cards!=="undefined"){
    const currentNames=[...cards].sort((a,b)=>b.name.length-a.name.length);
    for(const c of currentNames){
      const escaped=c.name.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
      const re=new RegExp("(^|[^A-Za-z])("+escaped+")(?=$|[^A-Za-z])","gi");
      html=html.replace(re,(m,prefix,name)=>`${prefix}<span class="card-ref-preview" data-ref-card="${c.n}">${name}</span>`);
    }
  }
  return html;
}
async function showCardPreview(number,event){
  await Promise.all([loadCardImageData(),loadCardRulesData()]);
  let card=cards.find(x=>x.n===+number),url=cardImageByNumber[String(number)];if(!card)return;
  let info=cardRulesByName[card.name.toLowerCase()]||null;
  let box=document.getElementById("cardPreview"),img=document.getElementById("cardPreviewImg");
  if(url){img.src=url;img.alt=card.name;img.style.display="block"}else{img.removeAttribute("src");img.style.display="none"}
  document.getElementById("cardPreviewCaption").textContent=`#${card.n} · ${card.name} · ${label(card.color)} · ${card.rarity}`;
  let meta=[];
  if(info&&info.color&&info.color.length)meta.push(info.color.join(" / "));
  if(info){let d=diceDisplay(info);if(d)meta.push(d)}
  if(info&&info.timing&&info.timing.length)meta.push(info.timing.map(t=>t.replaceAll("_"," ")).join(" · "));
  document.getElementById("cardPreviewMeta").textContent=meta.join("  ·  ");
  box.classList.add("open");box.setAttribute("aria-hidden","false");
  if(window.innerWidth>700)positionCardPreview(event);
}
function positionCardPreview(event){
  let box=document.getElementById("cardPreview"),gap=16,w=235,h=350,x=event.clientX+gap,y=event.clientY+gap;
  if(x+w>window.innerWidth-8)x=event.clientX-w-gap;
  if(y+h>window.innerHeight-8)y=Math.max(8,window.innerHeight-h-8);
  box.style.left=Math.max(8,x)+"px";box.style.top=Math.max(8,y)+"px";
}
function hideCardPreview(){let b=document.getElementById("cardPreview");b.classList.remove("open");b.setAttribute("aria-hidden","true")}
document.addEventListener("mouseover",e=>{let n=e.target.closest(".card-name-preview");if(n&&window.innerWidth>700)showCardPreview(n.dataset.cardNumber,e)});
document.addEventListener("mousemove",e=>{if(window.innerWidth>700&&document.getElementById("cardPreview").classList.contains("open"))positionCardPreview(e)});
document.addEventListener("mouseout",e=>{let n=e.target.closest(".card-name-preview");if(n&&window.innerWidth>700)hideCardPreview()});
document.addEventListener("click",e=>{
 let n=e.target.closest(".card-name-preview");
 if(window.innerWidth<=700&&n){e.stopPropagation();showCardPreview(n.dataset.cardNumber,e);return}
 if(window.innerWidth<=700&&!e.target.closest("#cardPreview"))hideCardPreview();
});
